// Package desktop holds the bits that make am-server feel like a desktop
// program on Windows: tray icon, opening the browser, start with Windows,
// message boxes, and attaching to a console when started from a terminal.
// On other systems the same functions exist and do the sensible minimum.
package desktop

import (
	_ "embed"
	"encoding/binary"
)

// IconICO is the AM icon (tray, window). Generated by assets/make_icon.py.
//
//go:embed icon.ico
var IconICO []byte

// TrayMenu describes the tray icon's menu actions.
type TrayMenu struct {
	Tooltip   string
	OnOpen    func() // also on double-click where supported
	OnRestart func()
	OnQuit    func()
}

// icoImage returns the image data of the entry in an .ico file closest to
// (and preferably not smaller than) size.
func icoImage(ico []byte, size int) []byte {
	if len(ico) < 6 || binary.LittleEndian.Uint16(ico[2:]) != 1 {
		return nil
	}
	n := int(binary.LittleEndian.Uint16(ico[4:]))
	best, bestSize := -1, 0
	for i := 0; i < n; i++ {
		e := 6 + 16*i
		if e+16 > len(ico) {
			return nil
		}
		w := int(ico[e])
		if w == 0 {
			w = 256
		}
		better := best < 0 ||
			(w >= size && (bestSize < size || w < bestSize)) ||
			(w < size && bestSize < size && w > bestSize)
		if better {
			best, bestSize = i, w
		}
	}
	if best < 0 {
		return nil
	}
	e := 6 + 16*best
	length := int(binary.LittleEndian.Uint32(ico[e+8:]))
	offset := int(binary.LittleEndian.Uint32(ico[e+12:]))
	if offset < 0 || length <= 0 || offset+length > len(ico) {
		return nil
	}
	return ico[offset : offset+length]
}
